    sort_numbers()
    print(sort_words_by_length(["python", "c", "java", "go"]))
    print("по второму элементу:", sorted([("a", 3), ("b", 1)], key=itemgetter(1)))

    students = [Student("Анна", 90), Student("Борис", 90), Student("Вера", 95)]
    for student in sort_students(students):
        print(student)


